mapper.select:
select id,user_id,user_name,login_name,gender,phone,
       active_status status, state,email,remark
from bp_user
where is_deleted = 0 and id != 1

    and user_id = #{id}


    and user_name like concat('%',#{userName},'%')


    and login_name like concat('%',#{loginName},'%')


    and phone like concat('%',#{phone},'%')


    and active_status = #{status}


    and state = #{state}


    and gender = #{gender}

order by create_time desc ,id asc

select distinct t3.NAME,t3.parent_id,t3.is_menu,t3.sort
from bp_user_role t1
    join bp_role_menu t2 on t1.role_id = t2.role_id
    join bp_menu t3 on t2.menu_id = t3.id
where t1.user_id=#{userId}
  and t1.is_deleted=0
  and t3.is_deleted=0

    and t3.parent_id = #{menuId}


    and t3.parent_id = #{parentId}

SELECT DISTINCT u.user_id, u.user_name, u.login_name FROM bp_user u JOIN bp_user_dept d ON u.user_id = d.user_id WHERE u.is_deleted = 0 and d.is_deleted = 0
and d.dept_id in
#{deptId}

SELECT DISTINCT u.user_id, u.user_name, u.login_name FROM bp_user u join bp_user_role r on u.user_id = r.user_id and r.is_deleted = 0 where u.is_deleted = 0
and r.role_id in
#{rId}
